];
const STRENGTH = { 强: 3, 中: 2, 弱: 1, 无: 0 };
const unproven = (m) => m.verdict !== '伪壁垒' && !(m.theses || []).some((x) => x.category === '壁垒');

function Bars({ v }) {
  const { t } = useUI();
  const n = STRENGTH[v] ?? 0;
