            <Lines series={series} years={years} fmt={(v) => (v === null || v === undefined ? '—' : Number(v).toFixed(2))} width={w} />
          </div>
        ) : null}
        <div style={{ display: 'grid', gridTemplateColumns: `repeat(${w >= 720 ? Math.min(scens.length, 3) : 1}, minmax(0,1fr))`, gap: 14 }}>
