    const keep = (f) => (1 - f.tax_rate) * (1 - f.minority_share);
    const shockFlows = (k) => flowsOf(base, (p, f) => {
      const dPretax = (k.rev ? k.rev * p.revenue : 0) - (k.cost ? k.cost * p.cash_cost : 0)
        - (k.kd ? k.kd * (Number(f.debt_open) + Number(f.debt_close)) / 2 : 0);
