            </Col>
          </Row>
          <Alert showIcon type={ok(baseIrr) ? 'success' : 'warning'} style={{ marginBottom: 12 }} message={verdict}
            description={isNum(baseIrr) && isNum(rf) ? `基准回报比 10 年国债${baseIrr >= rf ? '高' : '低'} ${pp(baseIrr - rf)}。研究提示，不是交易指令。` : null} />

