      <Attrs items={[['等级', <Status label={r.level || '未评'} color={level[r.level]} size={15} strong />], ['可能性', r.probability], ['冲击', r.impact], ['时间窗口', r.horizon]]} />
      <Section label="估值里怎么处理" text={r.treatment} refs={refs} tone="key" />
