// 商业模式画布：左半边怎么做（合作、业务、资源），右半边为谁做（关系、渠道、客户），中间价值主张，底部成本与收入
const AREA = { 重要合作: 'kp', 关键业务: 'ka', 核心资源: 'kr', 价值主张: 'vp', 客户关系: 'cr', 渠道通路: 'ch', 客户细分: 'cs', 成本结构: 'cost', 收入来源: 'rev' };

function Cell({ r, element, selected, onSelect, tall, core }) {
