  const on = single && isFlow;
  const m = matrix(ROWS[stmt], on);
  const shown = m.periods.slice(0, win > 0 ? win : undefined);
  const columns = [
    { title: '科目', dataIndex: 'item', fixed: 'left', width: 230,
