      </div>),
      dataIndex: p, align: 'right', width: 118,
      render: (v) => fmt(v),
    })),
  ];
  const dataSource = m.items.map((item) => {
    const row = { key: item, item };
    for (const p of shown) row[p] = m.value(item, p);
    return row;
  });
  return (
    <div>
      <div style={{ marginBottom: 10 }}><Text type="secondary">{ROLE}</Text></div>
