        <Segmented value={stmt} onChange={setStmt} options={STMTS} />
        <Segmented value={on ? '单季' : '累计'} onChange={(v) => setSingle(v === '单季')} options={isFlow ? ['累计', '单季'] : ['累计']} />
        <Select value={win} onChange={setWin} style={{ width: 108 }}
